package com.pethop.report;
import com.pethop.common.response.PageResponse; import com.pethop.report.dto.*; import com.pethop.security.SecurityUser; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.UUID; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController public class ReportController{private final ReportService service;public ReportController(ReportService s){service=s;}@GetMapping("/api/v1/admin/reports")PageResponse<ReportResponse> list(@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="25")@Min(1)@Max(100)int size){return service.list(page,size);}@PatchMapping("/api/v1/admin/reports/{id}")ReportResponse act(@PathVariable UUID id,@AuthenticationPrincipal SecurityUser admin,@Valid@RequestBody ReportActionRequest request){return service.act(id,admin,request);}}
